), inserted as (
  insert into public.sites (slug, draft_config, published_config, updated_at)
    select slug, config, config, coalesce((config ->> 'updatedAt')::timestamptz, now())
    from fixtures
    on conflict (slug) do nothing
    returning id, published_config, updated_at
)
insert into public.site_versions (site_id, config, published_at, note)
  select id, published_config, updated_at, 'Initial fixture' from inserted;
